package cli

import (
	"fmt"
	"os"
	"strconv"

	"github.com/jdbencardinop/tesseraworkspaces/internal"
	"github.com/spf13/cobra"
)

func configCmd() *cobra.Command {
	cmd := &cobra.Command{
		Use:   "config",
		Short: "Manage configuration",
	}

	cmd.AddCommand(configShowCmd())
	cmd.AddCommand(configSetCmd())
	cmd.AddCommand(configGetCmd())

	return cmd
}

func configShowCmd() *cobra.Command {
	return &cobra.Command{
		Use:   "show",
		Short: "Show resolved configuration",
		Args:  cobra.NoArgs,
		Run: func(cmd *cobra.Command, args []string) {
			cfg := internal.LoadConfig()

			fmt.Println("# Resolved configuration (global + per-repo)")
			fmt.Printf("agent_command: %s\n", cfg.GetAgentCommand())
			if cfg.UseTmux != nil {
				fmt.Printf("use_tmux: %v\n", *cfg.UseTmux)
			} else {
				fmt.Println("use_tmux: false (default)")
			}
			if cfg.InjectInto != "" {
				fmt.Printf("inject_into: %s\n", cfg.InjectInto)
			} else {
				fmt.Println("inject_into: . (default, worktree root)")
			}
			if cfg.TestCommand != "" {
				fmt.Printf("test_command: %s\n", cfg.TestCommand)
			} else {
				fmt.Println("test_command: (none)")
			}
			if cfg.AutoHooks != nil {
				fmt.Printf("auto_hooks: %v\n", *cfg.AutoHooks)
			} else {
				fmt.Println("auto_hooks: false (default)")
			}
			if cfg.BranchPrefix != "" {
				fmt.Printf("branch_prefix: %s\n", cfg.BranchPrefix)
			} else {
				fmt.Println("branch_prefix: (none)")
			}
			if len(cfg.Workspaces) > 0 {
				fmt.Println("workspaces:")
				for k, v := range cfg.Workspaces {
					fmt.Printf("  %s: %s\n", k, v)
				}
			}
			fmt.Println()
			fmt.Println("# Paths")
			fmt.Printf("global: %s\n", internal.ConfigPath())
			repoPath := internal.RepoConfigPath()
			if repoPath != "" {
				fmt.Printf("repo:   %s\n", repoPath)
			}
		},
	}
}

func configSetCmd() *cobra.Command {
	var repo bool

	cmd := &cobra.Command{
		Use:   "set <key> <value>",
		Short: "Set a config value",
		Args:  cobra.ExactArgs(2),
		ValidArgsFunction: func(cmd *cobra.Command, args []string, toComplete string) ([]string, cobra.ShellCompDirective) {
			if len(args) == 0 {
				return []string{"agent_command", "use_tmux", "inject_into", "test_command", "auto_hooks", "branch_prefix"}, cobra.ShellCompDirectiveNoFileComp
			}
			if len(args) == 1 && args[0] == "agent_command" {
				return []string{"claude", "opencode", "aider", "copilot"}, cobra.ShellCompDirectiveNoFileComp
			}
			if len(args) == 1 && args[0] == "use_tmux" {
				return []string{"true", "false"}, cobra.ShellCompDirectiveNoFileComp
			}
			return nil, cobra.ShellCompDirectiveNoFileComp
		},
		Run: func(cmd *cobra.Command, args []string) {
			key, value := args[0], args[1]

			path := internal.ConfigPath()
			if repo {
				path = internal.RepoConfigPath()
				if path == "" {
					fmt.Println("Error: not inside a git repository")
					os.Exit(1)
				}
			}

			cfg := internal.LoadConfigFile(path)

			switch key {
			case "agent_command":
				cfg.AgentCommand = value
			case "use_tmux":
				b, err := strconv.ParseBool(value)
				if err != nil {
					fmt.Printf("Error: use_tmux must be true or false, got %q\n", value)
					os.Exit(1)
				}
				cfg.UseTmux = &b
			case "inject_into":
				cfg.InjectInto = value
			case "test_command":
				cfg.TestCommand = value
			case "auto_hooks":
				b, err := strconv.ParseBool(value)
				if err != nil {
					fmt.Printf("Error: auto_hooks must be true or false, got %q\n", value)
					os.Exit(1)
				}
				cfg.AutoHooks = &b
			case "branch_prefix":
				cfg.BranchPrefix = value
			default:
				fmt.Printf("Unknown key: %s (valid: agent_command, use_tmux, inject_into, test_command, auto_hooks)\n", key)
				os.Exit(1)
			}

			if err := internal.SaveConfigFile(path, cfg); err != nil {
				fmt.Printf("Error saving config: %v\n", err)
				os.Exit(1)
			}

			scope := "global"
			if repo {
				scope = "repo"
			}
			fmt.Printf("Set %s = %s (%s: %s)\n", key, value, scope, path)
		},
	}

	cmd.Flags().BoolVar(&repo, "repo", false, "Edit per-repo config instead of global")

	return cmd
}

func configGetCmd() *cobra.Command {
	return &cobra.Command{
		Use:   "get <key>",
		Short: "Get a resolved config value",
		Args:  cobra.ExactArgs(1),
		ValidArgsFunction: func(cmd *cobra.Command, args []string, toComplete string) ([]string, cobra.ShellCompDirective) {
			return []string{"agent_command", "use_tmux", "inject_into", "test_command", "auto_hooks", "branch_prefix"}, cobra.ShellCompDirectiveNoFileComp
		},
		Run: func(cmd *cobra.Command, args []string) {
			cfg := internal.LoadConfig()

			switch args[0] {
			case "agent_command":
				fmt.Println(cfg.GetAgentCommand())
			case "use_tmux":
				if cfg.UseTmux != nil {
					fmt.Println(*cfg.UseTmux)
				} else {
					fmt.Println("false")
				}
			case "inject_into":
				if cfg.InjectInto != "" {
					fmt.Println(cfg.InjectInto)
				} else {
					fmt.Println(".")
				}
			case "test_command":
				if cfg.TestCommand != "" {
					fmt.Println(cfg.TestCommand)
				} else {
					fmt.Println("(none)")
				}
			case "auto_hooks":
				if cfg.AutoHooks != nil {
					fmt.Println(*cfg.AutoHooks)
				} else {
					fmt.Println("false")
				}
			case "branch_prefix":
				if cfg.BranchPrefix != "" {
					fmt.Println(cfg.BranchPrefix)
				} else {
					fmt.Println("(none)")
				}
			default:
				fmt.Printf("Unknown key: %s (valid: agent_command, use_tmux, inject_into, test_command, auto_hooks)\n", args[0])
				os.Exit(1)
			}
		},
	}
}

package cli

import (
	"fmt"
	"os"
	"os/exec"
	"strings"

	"github.com/jdbencardinop/tesseraworkspaces/internal"
	"github.com/spf13/cobra"
)

func newCmd() *cobra.Command {
	var base string
	var force bool
	var repo string

	cmd := &cobra.Command{
		Use:   "new <feature> <branch>",
		Short: "Create a worktree branch",
		Args:  cobra.ExactArgs(2),
		ValidArgsFunction: func(cmd *cobra.Command, args []string, toComplete string) ([]string, cobra.ShellCompDirective) {
			switch len(args) {
			case 0:
				return internal.ListFeatures(), cobra.ShellCompDirectiveNoFileComp
			case 1:
				return internal.ListBranches(args[0]), cobra.ShellCompDirectiveNoFileComp
			default:
				return nil, cobra.ShellCompDirectiveNoFileComp
			}
		},
		Run: func(cmd *cobra.Command, args []string) {
			if !cmd.Flags().Changed("base") {
				base = internal.DefaultBranch()
			}
			createWorktree(args[0], args[1], base, repo, force)
		},
	}

	cmd.Flags().StringVar(&base, "base", "", "Parent branch for stacking (default: repo's default branch)")
	cmd.Flags().BoolVarP(&force, "force", "f", false, "Force checkout of already checked-out branch")
	cmd.Flags().StringVar(&repo, "repo", "", "Source repository path (for cross-repo worktrees)")

	return cmd
}

// createWorktree is the shared logic for creating a worktree branch.
// Used by both tws new and tws add -n.
// repoPath is the source repo (empty = current repo).
func createWorktree(feature, name, base, repoPath string, force bool) {
	internal.RequireTool("git")

	featurePath := internal.FeaturePath(feature)
	path := internal.WorktreePath(feature, name) // worktree dir uses short name

	internal.Must(os.MkdirAll(featurePath, 0755))

	// Resolve the actual git branch name (apply prefix if configured)
	cfg := internal.LoadConfig()
	gitBranch := name
	if cfg.BranchPrefix != "" {
		gitBranch = cfg.BranchPrefix + name
	}

	// Determine which repo to use
	var repoRoot string
	if repoPath != "" {
		absRepo, err := internal.AbsPath(repoPath)
		if err != nil {
			fmt.Printf("Error: invalid repo path %s: %v\n", repoPath, err)
			os.Exit(1)
		}
		repoRoot = absRepo
		repoPath = absRepo
	} else {
		root, err := internal.MainRepoRoot()
		if err != nil {
			fmt.Println("Error: must be run from inside a git repository")
			os.Exit(1)
		}
		repoRoot = root
	}

	// Check if branch exists in the target repo (try both prefixed and unprefixed)
	branchExists := internal.RunSilent("git", "-C", repoRoot, "rev-parse", "--verify", gitBranch) == nil
	if !branchExists && gitBranch != name {
		// Try the unprefixed name (user may have created the branch manually)
		if internal.RunSilent("git", "-C", repoRoot, "rev-parse", "--verify", name) == nil {
			gitBranch = name // use the existing unprefixed branch
			branchExists = true
		}
	}

	if branchExists {
		if isCheckedOutIn(repoRoot, gitBranch) && !force {
			fmt.Printf("Warning: branch %q is already checked out in another worktree.\n", gitBranch)
			fmt.Println("Use --force to check it out anyway.")
			os.Exit(1)
		}

		gitArgs := []string{"worktree", "add"}
		if force {
			gitArgs = append(gitArgs, "--force")
		}
		gitArgs = append(gitArgs, path, gitBranch)
		internal.Must(internal.RunDir(repoRoot, "git", gitArgs...))
	} else {
		internal.Must(internal.RunDir(repoRoot, "git", "worktree", "add", path, "-b", gitBranch))
	}

	stack, _ := internal.LoadStack(featurePath)
	if !internal.HasBranch(stack, name) {
		entry := internal.StackEntry{
			Name: name,
			Base: base,
			Repo: repoPath,
		}
		// Only store Branch if it differs from Name
		if gitBranch != name {
			entry.Branch = gitBranch
		}
		stack.Branches = append(stack.Branches, entry)
		internal.Must(internal.SaveStack(featurePath, stack))
	}

	// Inject shared files into the worktree
	target := internal.ResolveInjectInto("")
	if err := internal.InjectFiles(featurePath, path, target); err != nil {
		fmt.Printf("Warning: inject failed: %v\n", err)
	}

	// Auto-install hooks if configured
	if cfg.AutoHooks != nil && *cfg.AutoHooks {
		if err := installHooksForWorktree(path, feature); err != nil {
			fmt.Printf("Warning: auto-hooks install failed: %v\n", err)
		}
	}

	if repoPath != "" {
		fmt.Printf("Worktree created: %s (base: %s, repo: %s)\n", path, base, repoPath)
	} else {
		fmt.Printf("Worktree created: %s (base: %s)\n", path, base)
	}
}

// isCheckedOutIn checks if a branch is checked out in any worktree of the given repo.
func isCheckedOutIn(repoDir, branch string) bool {
	out, err := exec.Command("git", "-C", repoDir, "worktree", "list", "--porcelain").Output()
	if err != nil {
		return false
	}
	for _, line := range strings.Split(string(out), "\n") {
		if strings.TrimSpace(line) == "branch refs/heads/"+branch {
			return true
		}
	}
	return false
}

package cli

import (
	"fmt"
	"os"
	"path/filepath"
	"strings"

	"github.com/jdbencardinop/tesseraworkspaces/internal"
)

func syncWithStack(feature, featurePath string, stack internal.Stack, sorted []internal.StackEntry) {
	syncWithStackFiltered(feature, featurePath, stack, sorted, nil)
}

func syncWithStackFiltered(feature, featurePath string, stack internal.Stack, sorted []internal.StackEntry, alreadyDone map[string]bool) {
	skipped := make(map[string]bool)
	updatedByRef := make(map[string]bool)
	completed := make([]string, 0)

	// Collect already-done branches from --continue
	if alreadyDone == nil {
		alreadyDone = make(map[string]bool)
	}

	// Pass 1: rebase active branches with --update-refs
	for _, entry := range sorted {
		if skipped[entry.Name] || alreadyDone[entry.Name] {
			continue
		}

		path := internal.WorktreePath(feature, entry.Name)
		if _, err := os.Stat(path); os.IsNotExist(err) {
			continue
		}

		// Health check: verify worktree is on the expected branch
		if issue := internal.CheckWorktreeBranch(path, entry.Name); issue != nil {
			fmt.Println(formatSyncStatus(entry.Name, "active", "wrong-branch"))
			fmt.Printf("    %s\n", issue.Problem)
			fmt.Printf("    %s\n", issue.Hint)
			skipDescendants(stack, entry.Name, skipped)
			continue
		}

		base := resolveBase(entry.Base)

		// Determine git context for resolving SHAs
		gitContext := path
		if entry.Repo != "" {
			gitContext = entry.Repo
		}

		// Build rebase args — use --onto if we have a previous base SHA
		// to avoid ghost conflicts from amended commits
		var rebaseArgs []string
		currentBaseSHA := internal.GetBranchSHA(gitContext, base)
		if entry.LastBaseSHA != "" && currentBaseSHA != "" && entry.LastBaseSHA != currentBaseSHA {
			// Base has changed (amended/rebased) — use --onto to skip stale commits
			rebaseArgs = []string{"rebase", "--update-refs", "--onto", base, entry.LastBaseSHA}
		} else {
			rebaseArgs = []string{"rebase", "--update-refs", base}
		}

		err := internal.RunDirClean(path, "git", rebaseArgs...)
		if err != nil {
			fmt.Println(formatSyncStatus(entry.Name, "active", "conflict"))

			// Collect pending branches
			pending := collectPending(sorted, entry.Name, skipped, alreadyDone, completed)
			skippedList := collectSkippedNames(stack, entry.Name)

			// Save state for --continue
			state := internal.NewSyncState()
			state.FailedBranch = entry.Name
			state.Pending = pending
			state.Completed = completed
			state.Skipped = skippedList
			_ = internal.SaveSyncState(featurePath, state)

			fmt.Printf("    Resolve conflicts in: %s\n", path)
			fmt.Println("    Then run: git add . && git rebase --continue")
			fmt.Printf("    Resume with: tws sync %s --continue\n", feature)
			skipDescendants(stack, entry.Name, skipped)
			return
		}

		// Post-rebase validation
		if !runValidation(path, entry.Name) {
			skipDescendants(stack, entry.Name, skipped)
		} else {
			fmt.Println(formatSyncStatus(entry.Name, "active", "synced"))
			markUpdatedAncestors(stack, entry.Name, featurePath, updatedByRef)
			completed = append(completed, entry.Name)

			// Update last_base_sha for next sync
			newBaseSHA := internal.GetBranchSHA(gitContext, base)
			if newBaseSHA != "" {
				internal.UpdateBaseSHA(&stack, entry.Name, newBaseSHA)
				_ = internal.SaveStack(featurePath, stack)
			}
		}
	}

	// Pass 2: handle archived/missing branches
	for _, entry := range sorted {
		if skipped[entry.Name] || alreadyDone[entry.Name] {
			if skipped[entry.Name] {
				fmt.Println(formatSyncStatus(entry.Name, "skipped", "skipped"))
			}
			continue
		}

		path := internal.WorktreePath(feature, entry.Name)
		if _, err := os.Stat(path); err == nil {
			continue
		}

		if internal.IsPrunableWorktree(entry.Name) {
			fmt.Printf("  [?] %s (missing — stale worktree ref, run: tws archive %s %s or tws new %s %s)\n",
				entry.Name, feature, entry.Name, feature, entry.Name)
			continue
		}

		if updatedByRef[entry.Name] {
			fmt.Println(formatSyncStatus(entry.Name, "archived", "synced"))
			continue
		}

		base := resolveBase(entry.Base)

		rebaseDir := ""
		if entry.Repo != "" {
			rebaseDir = entry.Repo
		}

		var rebaseErr error
		gitBranch := entry.GitBranch()
		if rebaseDir != "" {
			rebaseErr = internal.RunSilentDir(rebaseDir, "git", "rebase", base, gitBranch)
		} else {
			rebaseErr = internal.RunSilent("git", "rebase", base, gitBranch)
		}

		if rebaseErr != nil {
			if rebaseDir != "" {
				_ = internal.RunSilentDir(rebaseDir, "git", "rebase", "--abort")
			} else {
				_ = internal.RunSilent("git", "rebase", "--abort")
			}
			fmt.Println(formatSyncStatus(entry.Name, "archived", "conflict"))
			fmt.Printf("    Restore with: tws new %s %s\n", feature, entry.Name)
			skipDescendants(stack, entry.Name, skipped)
		} else {
			fmt.Println(formatSyncStatus(entry.Name, "archived", "synced"))
		}
	}

	// Clean up state if we completed everything
	internal.DeleteSyncState(featurePath)
}

func collectPending(sorted []internal.StackEntry, failedBranch string, skipped, done map[string]bool, completed []string) []string {
	completedSet := make(map[string]bool)
	for _, b := range completed {
		completedSet[b] = true
	}

	found := false
	var pending []string
	for _, entry := range sorted {
		if entry.Name == failedBranch {
			found = true
			continue
		}
		if found && !skipped[entry.Name] && !done[entry.Name] && !completedSet[entry.Name] {
			pending = append(pending, entry.Name)
		}
	}
	return pending
}

func collectSkippedNames(stack internal.Stack, branch string) []string {
	descs := internal.Descendants(stack, branch)
	var names []string
	for d := range descs {
		names = append(names, d)
	}
	return names
}

func resolveBase(base string) string {
	// If base is the repo's default branch, use its remote tracking ref
	defaultBranch := internal.DefaultBranch()
	if base == defaultBranch {
		return "origin/" + defaultBranch
	}
	return base
}

func markUpdatedAncestors(stack internal.Stack, branch string, featurePath string, updated map[string]bool) {
	entryMap := make(map[string]internal.StackEntry)
	for _, e := range stack.Branches {
		entryMap[e.Name] = e
	}

	current := branch
	for {
		entry, ok := entryMap[current]
		if !ok {
			break
		}
		parent, ok := entryMap[entry.Base]
		if !ok {
			break
		}
		parentPath := filepath.Join(featurePath, "worktrees", parent.Name)
		if _, err := os.Stat(parentPath); os.IsNotExist(err) {
			updated[parent.Name] = true
		}
		current = parent.Name
	}
}

func skipDescendants(stack internal.Stack, branch string, skipped map[string]bool) {
	descs := internal.Descendants(stack, branch)
	for d := range descs {
		skipped[d] = true
	}
	if len(descs) > 0 {
		fmt.Printf("    Skipping descendants: %s\n", internal.DescendantsList(stack, branch))
	}
}

func formatSyncStatus(name, mode, status string) string {
	symbols := map[string]string{
		"synced":            "+",
		"failed":            "x",
		"skipped":           "-",
		"conflict":          "!",
		"resolved":          "~",
		"wrong-branch":      "?",
		"validation-failed": "x",
	}
	sym := symbols[status]
	if sym == "" {
		sym = "?"
	}
	return fmt.Sprintf("  [%s] %s (%s)", sym, name, mode)
}

func syncFallback(featurePath string) {
	entries, _ := os.ReadDir(filepath.Join(featurePath, "worktrees"))
	for _, e := range entries {
		if !e.IsDir() {
			continue
		}
		path := filepath.Join(featurePath, "worktrees", e.Name())
		fmt.Printf("Syncing worktree: %s\n", path)
		internal.Must(internal.RunDirClean(path, "git", "rebase", "--update-refs", "origin/main"))
	}
}

// runValidation runs the configured test_command after a successful rebase.
func runValidation(worktreePath, branchName string) bool {
	cfg := internal.LoadConfig()
	if cfg.TestCommand == "" {
		return true
	}

	fmt.Printf("    validating %s: %s... ", branchName, cfg.TestCommand)
	parts := strings.Fields(cfg.TestCommand)
	err := internal.RunSilentDir(worktreePath, parts[0], parts[1:]...)
	if err != nil {
		fmt.Println("FAILED")
		fmt.Println(formatSyncStatus(branchName, "active", "validation-failed"))
		return false
	}
	fmt.Println("ok")
	return true
}

package internal

import (
	"os"
	"path/filepath"

	"gopkg.in/yaml.v3"
)

type Config struct {
	Workspaces   map[string]string `yaml:"workspaces"`
	AgentCommand string            `yaml:"agent_command"`
	UseTmux      *bool             `yaml:"use_tmux"`
	InjectInto   string            `yaml:"inject_into"`
	TestCommand  string            `yaml:"test_command"`
	AutoHooks    *bool             `yaml:"auto_hooks"`
	BranchPrefix string            `yaml:"branch_prefix"`
}

func (c Config) GetAgentCommand() string {
	if c.AgentCommand != "" {
		return c.AgentCommand
	}
	return "claude"
}

// ConfigPath returns the global config path.
func ConfigPath() string {
	home, _ := os.UserHomeDir()
	return filepath.Join(home, ".config", "tws", "config.yaml")
}

func repoConfigPath() string {
	root, err := RepoRoot()
	if err != nil {
		return ""
	}
	return filepath.Join(root, ".tws", "config.yaml")
}

func loadConfigFile(path string) Config {
	if path == "" {
		return Config{}
	}
	data, err := os.ReadFile(path)
	if err != nil {
		return Config{}
	}
	var cfg Config
	if err := yaml.Unmarshal(data, &cfg); err != nil {
		return Config{}
	}
	return cfg
}

// LoadConfig loads the global config, then merges per-repo config on top.
// Per-repo values override global values when set.
func LoadConfig() Config {
	cfg := loadConfigFile(ConfigPath())
	repo := loadConfigFile(repoConfigPath())

	if repo.AgentCommand != "" {
		cfg.AgentCommand = repo.AgentCommand
	}
	if repo.UseTmux != nil {
		cfg.UseTmux = repo.UseTmux
	}
	if repo.InjectInto != "" {
		cfg.InjectInto = repo.InjectInto
	}
	if repo.TestCommand != "" {
		cfg.TestCommand = repo.TestCommand
	}
	if repo.AutoHooks != nil {
		cfg.AutoHooks = repo.AutoHooks
	}
	if repo.BranchPrefix != "" {
		cfg.BranchPrefix = repo.BranchPrefix
	}
	if len(repo.Workspaces) > 0 {
		if cfg.Workspaces == nil {
			cfg.Workspaces = make(map[string]string)
		}
		for k, v := range repo.Workspaces {
			cfg.Workspaces[k] = v
		}
	}

	return cfg
}

// SaveConfigFile writes a config to the given path.
func SaveConfigFile(path string, cfg Config) error {
	dir := filepath.Dir(path)
	if err := os.MkdirAll(dir, 0755); err != nil {
		return err
	}
	data, err := yaml.Marshal(&cfg)
	if err != nil {
		return err
	}
	return os.WriteFile(path, data, 0644)
}

// RepoConfigPath exports the per-repo config path for the config command.
func RepoConfigPath() string {
	return repoConfigPath()
}

// LoadConfigFile loads a single config file (exported for the config command).
func LoadConfigFile(path string) Config {
	return loadConfigFile(path)
}

// TemplatePath returns the template directory path.
// Per-repo (.tws/templates/) takes priority over global (~/.config/tws/templates/).
// Returns empty string if neither exists.
func TemplatePath() string {
	// Per-repo first
	repoPath := repoConfigPath()
	if repoPath != "" {
		repoTemplates := filepath.Join(filepath.Dir(repoPath), "templates")
		if info, err := os.Stat(repoTemplates); err == nil && info.IsDir() {
			return repoTemplates
		}
	}

	// Global
	home, _ := os.UserHomeDir()
	globalTemplates := filepath.Join(home, ".config", "tws", "templates")
	if info, err := os.Stat(globalTemplates); err == nil && info.IsDir() {
		return globalTemplates
	}

	return ""
}

package internal

import (
	"fmt"
	"os"
	"os/exec"
	"path/filepath"
	"strings"
)

type HealthIssue struct {
	Branch  string
	Problem string
	Hint    string
}

func (h HealthIssue) String() string {
	s := fmt.Sprintf("  [!] %s: %s", h.Branch, h.Problem)
	if h.Hint != "" {
		s += fmt.Sprintf("\n      %s", h.Hint)
	}
	return s
}

// CheckWorktreeBranch verifies the worktree is on the expected branch.
func CheckWorktreeBranch(worktreePath, expectedBranch string) *HealthIssue {
	out, err := exec.Command("git", "-C", worktreePath, "rev-parse", "--abbrev-ref", "HEAD").Output()
	if err != nil {
		return &HealthIssue{
			Branch:  expectedBranch,
			Problem: "could not determine current branch",
			Hint:    fmt.Sprintf("check worktree at %s", worktreePath),
		}
	}

	actual := strings.TrimSpace(string(out))
	if actual != expectedBranch {
		return &HealthIssue{
			Branch:  expectedBranch,
			Problem: fmt.Sprintf("on branch %q, expected %q", actual, expectedBranch),
			Hint:    fmt.Sprintf("run: cd %s && git checkout %s", worktreePath, expectedBranch),
		}
	}
	return nil
}

// CheckWorktreeDirty checks if the worktree has uncommitted changes.
func CheckWorktreeDirty(worktreePath, branch string) *HealthIssue {
	out, err := exec.Command("git", "-C", worktreePath, "status", "--porcelain").Output()
	if err != nil {
		return nil
	}
	if len(strings.TrimSpace(string(out))) > 0 {
		return &HealthIssue{
			Branch:  branch,
			Problem: "has uncommitted changes",
			Hint:    "commit or stash changes before syncing",
		}
	}
	return nil
}

// CheckWorktreeInjectLinks checks if inject symlinks are present.
// Respects the configured inject_into target path.
func CheckWorktreeInjectLinks(featurePath, worktreePath, branch string) *HealthIssue {
	injectDir := InjectPath(featurePath)
	if _, err := os.Stat(injectDir); os.IsNotExist(err) {
		return nil // no inject dir, nothing to check
	}

	// Resolve inject target (respects inject_into config)
	targetBase := worktreePath
	injectInto := ResolveInjectInto("")
	if injectInto != "" && injectInto != "." {
		targetBase = filepath.Join(worktreePath, injectInto)
	}

	missing := 0
	_ = filepath.Walk(injectDir, func(srcPath string, info os.FileInfo, err error) error {
		if err != nil || info.IsDir() {
			return nil
		}
		relPath, err := filepath.Rel(injectDir, srcPath)
		if err != nil {
			return nil
		}
		destPath := filepath.Join(targetBase, relPath)
		if _, err := os.Lstat(destPath); os.IsNotExist(err) {
			missing++
		}
		return nil
	})

	if missing > 0 {
		return &HealthIssue{
			Branch:  branch,
			Problem: fmt.Sprintf("%d inject file(s) missing", missing),
			Hint:    fmt.Sprintf("run: tws inject <feature> %s", branch),
		}
	}
	return nil
}

// CheckFeatureHealth runs all health checks for a feature and returns issues.
func CheckFeatureHealth(featurePath string) []HealthIssue {
	var issues []HealthIssue

	stack, err := LoadStack(featurePath)
	if err != nil {
		return issues
	}

	for _, entry := range stack.Branches {
		wtPath := filepath.Join(featurePath, "worktrees", entry.Name)
		if _, err := os.Stat(wtPath); os.IsNotExist(err) {
			continue // archived, skip
		}

		if issue := CheckWorktreeBranch(wtPath, entry.GitBranch()); issue != nil {
			issues = append(issues, *issue)
		}
		if issue := CheckWorktreeDirty(wtPath, entry.Name); issue != nil {
			issues = append(issues, *issue)
		}
		if issue := CheckWorktreeInjectLinks(featurePath, wtPath, entry.Name); issue != nil {
			issues = append(issues, *issue)
		}
	}

	return issues
}

package internal

import (
	"fmt"
	"os"
	"os/exec"
	"path/filepath"
	"strings"

	"gopkg.in/yaml.v3"
)

type StackEntry struct {
	Name        string `yaml:"name"`
	Branch      string `yaml:"branch,omitempty"` // git branch name (defaults to Name if empty)
	Base        string `yaml:"base"`
	Repo        string `yaml:"repo,omitempty"`          // source repo path (empty = default/current repo)
	LastBaseSHA string `yaml:"last_base_sha,omitempty"` // SHA of base branch at last sync
}

// GitBranch returns the actual git branch name for this entry.
func (e StackEntry) GitBranch() string {
	if e.Branch != "" {
		return e.Branch
	}
	return e.Name
}

type Stack struct {
	Branches []StackEntry `yaml:"branches"`
}

// UniqueRepos returns a set of unique repo paths referenced in the stack.
// Empty string represents the default repo. Returns worktree paths for
// each repo (to use as git context) alongside the repo path.
func UniqueRepos(s Stack, featurePath string) map[string]string {
	repos := make(map[string]string)
	for _, e := range s.Branches {
		repo := e.Repo
		if _, ok := repos[repo]; !ok {
			// Find an active worktree from this repo to use as git context
			wtPath := filepath.Join(featurePath, "worktrees", e.Name)
			if _, err := os.Stat(wtPath); err == nil {
				repos[repo] = wtPath
			} else {
				repos[repo] = "" // no active worktree, will need fallback
			}
		}
	}
	return repos
}

// HasBranch checks if a branch name already exists in the stack.
func HasBranch(s Stack, name string) bool {
	for _, e := range s.Branches {
		if e.Name == name {
			return true
		}
	}
	return false
}

// GetBranch returns the StackEntry for a branch name. Returns empty entry if not found.
func GetBranch(s Stack, name string) StackEntry {
	for _, e := range s.Branches {
		if e.Name == name {
			return e
		}
	}
	return StackEntry{}
}

// UpdateBaseSHA updates the last_base_sha for a branch in the stack.
func UpdateBaseSHA(s *Stack, branchName, sha string) {
	for i := range s.Branches {
		if s.Branches[i].Name == branchName {
			s.Branches[i].LastBaseSHA = sha
			return
		}
	}
}

// GetBranchSHA returns the current HEAD SHA of a branch using git.
func GetBranchSHA(gitContext, branch string) string {
	args := []string{"rev-parse", branch}
	if gitContext != "" {
		args = []string{"-C", gitContext, "rev-parse", branch}
	}
	out, err := exec.Command("git", args...).Output()
	if err != nil {
		return ""
	}
	return strings.TrimSpace(string(out))
}

// RenameBranch renames a branch in the stack, updating both Name and Base references.
func RenameBranch(s *Stack, oldName, newName string) bool {
	found := false
	for i := range s.Branches {
		if s.Branches[i].Name == oldName {
			s.Branches[i].Name = newName
			found = true
		}
		if s.Branches[i].Base == oldName {
			s.Branches[i].Base = newName
		}
	}
	return found
}

func StackPath(featurePath string) string {
	return filepath.Join(featurePath, "stack.yaml")
}

func LoadStack(featurePath string) (Stack, error) {
	data, err := os.ReadFile(StackPath(featurePath))
	if err != nil {
		return Stack{}, err
	}
	var s Stack
	if err := yaml.Unmarshal(data, &s); err != nil {
		return Stack{}, err
	}
	return s, nil
}

func SaveStack(featurePath string, s Stack) error {
	data, err := yaml.Marshal(&s)
	if err != nil {
		return err
	}
	return os.WriteFile(StackPath(featurePath), data, 0644)
}

// TopoSort returns branches in dependency order (parents before children).
// Returns an error if the graph contains a cycle.
func TopoSort(s Stack) ([]StackEntry, error) {
	// Build adjacency: base → children
	entryMap := make(map[string]StackEntry)
	children := make(map[string][]string)
	inDegree := make(map[string]int)

	for _, e := range s.Branches {
		entryMap[e.Name] = e
		inDegree[e.Name] = 0
	}

	for _, e := range s.Branches {
		// Only count edges where the base is also a tracked branch
		if _, ok := entryMap[e.Base]; ok {
			children[e.Base] = append(children[e.Base], e.Name)
			inDegree[e.Name]++
		}
	}

	// Kahn's algorithm
	var queue []string
	for name, deg := range inDegree {
		if deg == 0 {
			queue = append(queue, name)
		}
	}

	var sorted []StackEntry
	for len(queue) > 0 {
		name := queue[0]
		queue = queue[1:]
		sorted = append(sorted, entryMap[name])
		for _, child := range children[name] {
			inDegree[child]--
			if inDegree[child] == 0 {
				queue = append(queue, child)
			}
		}
	}

	if len(sorted) != len(s.Branches) {
		return nil, fmt.Errorf("cycle detected in stack.yaml")
	}
	return sorted, nil
}

// Descendants returns all transitive children of the given branch.
func Descendants(s Stack, branch string) map[string]bool {
	children := make(map[string][]string)
	for _, e := range s.Branches {
		children[e.Base] = append(children[e.Base], e.Name)
	}

	result := make(map[string]bool)
	queue := []string{branch}
	for len(queue) > 0 {
		name := queue[0]
		queue = queue[1:]
		for _, child := range children[name] {
			if !result[child] {
				result[child] = true
				queue = append(queue, child)
			}
		}
	}
	return result
}

// PrintTree prints the stack as an indented dependency tree.
func PrintTree(s Stack) {
	children := make(map[string][]string)
	roots := make(map[string]bool)

	for _, e := range s.Branches {
		roots[e.Name] = true
	}
	for _, e := range s.Branches {
		children[e.Base] = append(children[e.Base], e.Name)
		// If base is a tracked branch, this entry is not a root
		for _, other := range s.Branches {
			if other.Name == e.Base {
				delete(roots, e.Name)
				break
			}
		}
	}

	var printNode func(name, prefix string, isLast bool)
	printNode = func(name, prefix string, isLast bool) {
		connector := "├── "
		if isLast {
			connector = "└── "
		}
		fmt.Println(prefix + connector + name)

		childPrefix := prefix
		if isLast {
			childPrefix += "    "
		} else {
			childPrefix += "│   "
		}

		kids := children[name]
		for i, child := range kids {
			printNode(child, childPrefix, i == len(kids)-1)
		}
	}

	// Print from each root's base (usually "main")
	bases := make(map[string]bool)
	for _, e := range s.Branches {
		if roots[e.Name] {
			bases[e.Base] = true
		}
	}

	for base := range bases {
		fmt.Printf("(%s)\n", base)
		kids := children[base]
		for i, child := range kids {
			printNode(child, "", i == len(kids)-1)
		}
	}

	if len(s.Branches) == 0 {
		fmt.Println("No branches tracked. Use 'ts new <feature> <branch>' to add branches.")
	}
}

// FormatBranchStatus formats a branch sync result for display.
func FormatBranchStatus(name, status string) string {
	symbols := map[string]string{
		"synced":  "+",
		"failed":  "x",
		"skipped": "-",
	}
	sym := symbols[status]
	if sym == "" {
		sym = "?"
	}
	return fmt.Sprintf("  [%s] %s", sym, name)
}

// DescendantsList returns Descendants as a sorted display string.
func DescendantsList(s Stack, branch string) string {
	descs := Descendants(s, branch)
	var names []string
	for name := range descs {
		names = append(names, name)
	}
	return strings.Join(names, ", ")
}
